<template><section class="page flex flex-col min-h-[840px]"><div class="flex justify-center mt-14"><div class="w-14 h-14 rounded-2xl bg-[#0a84ff] text-white grid place-items-center text-2xl"><i class="fa-solid fa-droplet"/></div></div><h1 class="text-center text-3xl font-bold mt-5">欢迎回到糖安</h1><p class="text-center muted text-sm mt-2">记录每一次变化，管理每一天状态</p><form class="mt-9 space-y-4" @submit.prevent="submit"><label class="block text-sm font-medium">手机号或邮箱<input v-model="account" class="w-full mt-2 p-4 rounded-xl border-0 bg-white" required placeholder="请输入手机号或邮箱"/></label><label class="block text-sm font-medium">密码<input v-model="password" class="w-full mt-2 p-4 rounded-xl border-0 bg-white" required minlength="6" type="password" placeholder="至少 6 位密码"/></label><button class="btn-primary mt-2">登录</button><p class="text-center text-xs text-[#ff3b30] min-h-4">{{ error }}</p></form><div class="mt-auto"><p class="text-center text-sm muted">还没有糖安账号？</p><RouterLink to="/register" class="btn-secondary mt-3">创建新账号</RouterLink></div></section></template>
<script setup lang="ts">
import { ref } from 'vue';import { useRouter } from 'vue-router';import { useStore } from 'vuex';import type { RootState } from '../main';const router=useRouter();const store=useStore<RootState>();const account=ref('13800000000');const password=ref('123456');const error=ref('');const loading=ref(false);async function submit(){if(password.value.length<6){error.value='密码至少 6 位';return}loading.value=true;error.value='';try{await store.dispatch('auth/login',{account:account.value,password:password.value});router.push('/home')}catch(e){error.value=e instanceof Error?e.message:'登录失败，请稍后重试'}finally{loading.value=false}}</script>


